package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TokenBuffer#writeObject
 */
public class TokenBuffer_writeObject_TriageGen2Test {

    private ObjectMapper mapper;
    private ObjectCodec codec;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        codec = mapper.getCodec();
    }

    @Test
    public void testWriteObjectWithCodec() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(codec);
        String testValue = "{\"key\":\"value\"}";
        // We use a Map or a POJO to test actual object serialization via the buffer logic
        java.util.Map<String, String> testMap = java.util.Collections.singletonMap("key", "value");

        // Act
        buffer.writeObject(testMap);

        // Assert
        // Since writeObject calls _append(VALUE_EMBEDDED_OBJECT, value), 
        // we verify the token type and the ability to serialize it back.
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, buffer.firstToken());

        // Verify that we can serialize the buffer content to a generator and it matches the expected JSON
        JsonGenerator gen = mapper.getFactory().createGenerator(new java.io.StringWriter());
        buffer.serialize(gen);
        gen.close();

        // The buffer contains the embedded object. When serialized, it should represent the map.
        // Note: TokenBuffer's behavior with VALUE_EMBEDDED_OBJECT is to store the reference.
        // When serialize() is called, it uses the codec to write that object.
    }

    @Test
    public void testWriteObjectWithNull() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(codec);

        // Act
        buffer.writeObject(null);

        // Assert
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, buffer.firstToken());
    }

    @Test
    public void testWriteObjectWithoutCodec() throws IOException {
        // Arrange
        // Constructor with null codec to test the "Tricky choice" mentioned in the comments
        TokenBuffer buffer = new TokenBuffer((ObjectCodec) null);
        String testValue = "some object";

        // Act
        // The comment says: "if no codec, should we err out, or just embed? For now, do latter."
        // This means it should NOT throw an exception during writeObject.
        buffer.writeObject(testValue);

        // Assert
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, buffer.firstToken());

        // When attempting to serialize a buffer that has an embedded object but no codec,
        // it should eventually fail or handle it depending on the implementation of serialize.
        // But the primary goal of writeObject is to ensure it doesn't throw.
    }

    @Test
    public void testWriteObjectWithComplexType() throws IOException {
        // Arrange
        TokenBuffer buffer = new TokenBuffer(codec);
        class ComplexObject {
            public int id = 1;
            public String name = "test";
        }
        ComplexObject obj = new ComplexObject();

        // Act
        buffer.writeObject(obj);

        // Assert
        assertEquals(JsonToken.VALUE_EMBEDDED_OBJECT, buffer.firstToken());
    }
}
